{"files": [{"path": "creative_intent.json", "content": "{
  "x_axis": {
    "id": "B9",
    "name": "大胆企图"
  },
  "y_axis_tags": ["刑侦悬疑"],
  "reaction_strength": "↘",
  "core_concept": "两个性格互补的发小为寻找二十年前失踪的父辈，进入西南横断山脉探险，全程以硬核野外生存为核心，应对山洪、滑坡、毒虫、高原反应、排外村寨等真实威胁，所有谜题均有历史学和地理学合理解释，无超自然元素，突出两人从互相争吵到生死托命的兄弟情。",
  "target_word_count": 120000,
  "tone": "硬核写实，冷峻扎实"
}"}, {"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "陈峰",
      "role": "protagonist",
      "identity": "退伍侦察兵，野外生存教练",
      "traits": ["粗犷耿直", "动手能力强", "嘴硬心软", "敬畏自然"],
      "overt_motivation": "找到二十年前进山失踪的父亲，查明当年队伍失踪的真相",
      "covert_motivation": "证明父亲不是当年队友口中抛弃同伴的逃兵",
      "secret_fear": "找到父亲的遗物时，发现他当年真的为了活命抛弃了队友",
      "misperception_of_other": "觉得林砚是肩不能扛手不能提的书呆子，进山只会拖后腿，不懂生命比研究重要",
      "hidden_connection": "小时候曾为了救落水的林砚，自己差点溺死，这件事他自己早就忘了，但林砚一直记着"
    },
    {
      "name": "林砚",
      "role": "deuteragonist",
      "identity": "考古系硕士研究生，精通唐代南诏历史与古文字",
      "traits": ["严谨细致", "记忆力超群", "认死理", "共情能力强"],
      "overt_motivation": "破解新出土唐代铜牌的秘密，找到传说中的南诏古城遗址",
      "covert_motivation": "完成父亲当年未竟的考古理想，弥补父亲一生的遗憾",
      "secret_fear": "自己研究了多年的南诏历史体系根本就是错的，父亲当年的研究方向完全走错了",
      "misperception_of_other": "觉得陈峰是只会动粗的大老粗，根本不懂考古研究的学术价值，眼里只有活命和寻父",
      "hidden_connection": "从小到大偷偷把陈峰当榜样，当年陈峰参军走的时候，他偷偷攒了三个月零花钱买了个军用指南针塞给陈峰"
    }
  ],
  "supporting_characters": [
    {
      "name": "老杨",
      "function": "助力",
      "identity": "横断山脉当地的纳西族老向导",
      "description": "二十年前曾给陈峰、林砚父亲的探险队当过向导，进山第五天因为脚伤提前下山，对当年队伍的部分内情知情，这么多年一直因为当年没能阻止队伍深入而愧疚，这次主动要求给两人带路，熟悉山里的地形、气候和周边村寨的规矩"
    },
    {
      "name": "阿黑",
      "function": "阻碍",
      "identity": "深山白族村寨的护林队队长",
      "description": "坚信外人进山会惊扰山神、破坏山里的平衡，二十年前曾阻拦过陈峰父亲的队伍，这次更是多次设置路障、销毁路标阻拦两人前进，熟悉山里的所有陷阱和隐蔽路线，是两人进山路上最大的人为阻碍"
    },
    {
      "name": "王叔",
      "function": "反转点",
      "identity": "当年探险队的唯一幸存者",
      "description": "当年探险队遭遇山洪时被落石砸断了腿，被当地村寨的人救下，之后就一直在山里隐居，知道当年队伍失踪的全部真相，是解开父辈失踪谜团的关键人物"
    }
  ],
  "relationship_dynamics": "陈峰和林砚是从小一起长大的邻居发小，少年时关系极好，后来陈峰参军、林砚上学，两人十多年很少联系，因为新出土的唐代铜牌重新聚到一起。初期两人互相看不顺眼，经常因为路线选择、是否触碰遗址物品、优先级是寻父还是考古频繁吵架，关系紧张；中期经历了山洪逃生、滑坡被困、被阿黑追杀几次生死危机后，逐渐意识到对方的价值，开始信任彼此；后期在古城遗址找到父辈的遗物和日记，解开所有谜团后，两人彻底冰释前嫌，成为可以托付后背的生死兄弟。"
}"}]}

